// Чёрный Врач / Black Physician (Дар Нургла, wdbc-1rno) — полное действие:
// пустить себе кровь и заразить ею до 3 трупов в 2 м.
// Автоматизировано то, что считается: 1 непоглощаемый R Dmg себе (общая
// арифметика потери Ран, woundLossUpdates), список подходящих тел вокруг и
// предел контроля Cor.b. Превращение трупов в зомби (A/I до 10, Раны ×2,
// снятие Навыков и не-оружейных Талантов) НЕ выполняется движком: это
// разрушительная правка чужих акторов, и «призыва существа вне слотов
// Миньонов» в системе всё равно нет — карточка называет цели и правила, МИ
// готовит зомби сам.
const casterTokenDoc = token?.document ?? token;
const corB = Number(actor.system?.corruptionBonus) || 0;

// 1 непоглощаемого R Dmg себе — цена Дара, берётся всегда.
await actor.update(woundLossUpdates(actor.system, 1));

// Подходящие тела: Раны −5 и ниже в пределах 2 м. Тот же порог, что у
// Стервятника (combat/vulture.mjs) — понятия «смерть» в системе нет, труп на
// сцене это токен с глубоко отрицательными Ранами.
let corpses = [];
if (casterTokenDoc?.parent) {
  const scene = casterTokenDoc.parent;
  const gridSize = scene.grid?.size || 100;
  const perMeter = gridSize / (scene.grid?.distance || 1);
  const cx = casterTokenDoc.x + (casterTokenDoc.width || 1) * gridSize / 2;
  const cy = casterTokenDoc.y + (casterTokenDoc.height || 1) * gridSize / 2;
  corpses = scene.tokens.contents.filter(t => {
    if (t.id === casterTokenDoc.id || !t.actor) return false;
    if ((Number(t.actor.system?.wounds?.critical) || 0) < 5) return false;
    const tx = t.x + (t.width || 1) * gridSize / 2;
    const ty = t.y + (t.height || 1) * gridSize / 2;
    return Math.hypot(tx - cx, ty - cy) / perMeter <= 2;
  }).slice(0, 3);
}

const list = corpses.length
  ? corpses.map(t => t.actor.name).join(", ")
  : "<i>тел с Ранами −5 и ниже в 2 м не найдено</i>";

await ChatMessage.create(ChatMessage.applyRollMode({
  speaker,
  content: `<div class="wh-roll-result">
    <div class="roll-header">Чёрный Врач — ${actor.name}</div>
    <div class="roll-threshold">Кровопускание: <b>1</b> непоглощаемого R Dmg себе.</div>
    <div class="roll-threshold">Заражены (до 3 тел в 2 м): ${list}</div>
    <div class="roll-threshold">Встанут зомби в начале следующего Хода чемпиона: A и I до 10, Раны ×2 от прижизненных, Навыки и Таланты сняты кроме оружейных. Под контролем — до <b>${corB}</b> (Cor.b); сверх этого зомби враждебны всем, кроме других зомби.</div>
    <div class="roll-threshold" style="opacity:.8;">Самих зомби готовит МИ: призыва существа вне слотов Миньонов в системе нет.</div>
  </div>`
}, game.settings.get("core", "rollMode")));
